-- Devis Studio CRM — migration 002_auth
--
-- Target: MySQL 8, InnoDB, utf8mb4. Import ONCE via phpMyAdmin into the CRM database
-- that already contains 001_init. Owner authentication only: there is no public
-- registration. Contains no users, no password hashes and no tokens; the owner row is
-- inserted manually with the output of api/bin/hash-owner-password.php.
--
-- Conventions as in 001_init:
--   * id columns: UUID strings generated by the application (CHAR(36), ascii_bin);
--   * timestamps: DATETIME(3) in UTC (the API sets time_zone = '+00:00' per session);
--   * secrets are never stored in plain form: passwords as password_hash() output,
--     session tokens as SHA-256 hex digests.

SET NAMES utf8mb4;

-- Created first and without IF NOT EXISTS: importing this file a second time fails
-- here, before any other table is touched.
-- The CRM owner. One row is expected; the schema does not need to forbid more.
CREATE TABLE `users` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  -- Stored lower-case (normalized by the application); unique case-insensitively.
  `login` VARCHAR(64) NOT NULL,
  -- password_hash() output (Argon2id or bcrypt); PHP recommends room for 255 characters.
  `password_hash` VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_login` (`login`),
  CONSTRAINT `chk_users_login_not_blank` CHECK (CHAR_LENGTH(TRIM(`login`)) > 0),
  CONSTRAINT `chk_users_password_hash_not_blank` CHECK (CHAR_LENGTH(`password_hash`) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Server-side sessions. The cookie carries a random token; only its SHA-256 digest is
-- stored, so a copy of this table does not yield usable sessions.
CREATE TABLE `sessions` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  -- Lower-case hex SHA-256 of the session token.
  `token_hash` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  -- Random per-session CSRF token (hex), required for state-changing requests.
  `csrf_token` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL,
  `last_seen_at` DATETIME(3) NOT NULL,
  `expires_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sessions_token_hash` (`token_hash`),
  KEY `idx_sessions_user` (`user_id`),
  -- Periodic removal of expired sessions.
  KEY `idx_sessions_expires_at` (`expires_at`),
  -- Deleting the owner ends all of their sessions.
  CONSTRAINT `fk_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
    ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_sessions_token_hash_length` CHECK (CHAR_LENGTH(`token_hash`) = 64),
  CONSTRAINT `chk_sessions_csrf_token_length` CHECK (CHAR_LENGTH(`csrf_token`) = 64),
  CONSTRAINT `chk_sessions_expiry_order` CHECK (`expires_at` > `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Login attempts for brute-force throttling (failures per login and per IP within a
-- time window). Recorded for unknown logins as well, so throttling does not reveal
-- which logins exist. Old rows are purged by the application.
CREATE TABLE `login_attempts` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  -- Login as typed, trimmed and lower-cased; longer input is rejected before recording.
  `login_normalized` VARCHAR(64) NOT NULL,
  -- Client IP in text form (IPv4 or IPv6, up to 45 characters).
  `ip_address` VARCHAR(45) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `attempted_at` DATETIME(3) NOT NULL,
  `succeeded` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_login_attempts_login_time` (`login_normalized`, `attempted_at`),
  KEY `idx_login_attempts_ip_time` (`ip_address`, `attempted_at`),
  KEY `idx_login_attempts_time` (`attempted_at`),
  CONSTRAINT `chk_login_attempts_succeeded` CHECK (`succeeded` IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `schema_migrations` (`version`) VALUES ('002_auth');
